import { toPaise } from '@kreaton/core';
import type { Paise, Typology, VpaEntryMethod } from '@kreaton/core';

/**
 * Scam typologies and their behavioural fingerprints.
 *
 * This file is the substantive content of the generated corpus. Fraud is not
 * modelled as a random label sprinkled over transactions: each fraudulent
 * payment is produced by one of eight documented scam types, and each type has
 * a distinct observable fingerprint because the social engineering that drives
 * it is distinct.
 *
 * That distinction is what makes the evaluation meaningful. If fraud were
 * generated by perturbing a few fields at random, a detector would be measuring
 * its ability to find the perturbation rather than its ability to find fraud,
 * and every reported metric would be circular. Here, the contextual signals have
 * to earn their discrimination against eight genuinely different patterns, some
 * of which, notably marketplace purchase scams, are deliberately hard.
 *
 * On provenance, stated plainly: the typology set and the relative shares
 * reflect the pattern of authorised push payment fraud reported publicly in
 * India, where task-based job scams and investment scams dominate by volume and
 * value respectively and coercive impersonation, the so-called digital arrest,
 * produces the largest individual losses. The specific distribution parameters
 * are calibrated estimates chosen to produce realistic marginals, not
 * measurements from proprietary data. docs/MODELING.md records the reasoning
 * per parameter and reports how sensitive the results are to each.
 */

export interface TypologySpec {
  id: Typology;
  label: string;
  /** Share of all fraudulent payments. Shares sum to 1. */
  share: number;
  /** What the scam is, in a sentence. */
  description: string;
  /** Why the fingerprint below looks the way it does. */
  fingerprint: string;

  /** Amount drawn lognormally in paise log space. */
  amountLogMean: number;
  amountLogSd: number;
  amountFloor: Paise;
  amountCeiling: Paise;

  /** Probability a call is in progress at authorisation. */
  activeCallProb: number;
  /** Mean call duration at authorisation, in seconds. */
  callSecondsMean: number;
  screenShareProb: number;
  remoteAccessProb: number;

  /** Mean in-session application switches before authorisation. */
  appSwitchMean: number;
  /** Mean seconds from app open to authorisation. */
  authorizeSecondsMean: number;
  entryMix: Record<VpaEntryMethod, number>;

  /** Probability the payer is steered to keep amounts under a threshold. */
  structuringProb: number;
  /** Probability the payment is made from an unrecognised device. */
  newDeviceProb: number;

  /** Relative hour-of-day weights over IST, reflecting the operator schedule. */
  hourWeights: number[];
  /** Payments extracted from one victim in a single episode. */
  episodeMin: number;
  episodeMax: number;
  /**
   * Probability that a later episode against the same victim reuses a
   * collection account they have already paid.
   *
   * This is what stops beneficiary novelty from becoming a proxy for the label.
   * Several typologies involve a sustained relationship in which the victim
   * pays the same account repeatedly over weeks: a romance scam runs on one
   * trusted counterparty, and an investment scam keeps the victim depositing to
   * the same platform account. By the third payment that beneficiary is no
   * longer new, and a system that relies on novelty alone has already stopped
   * seeing it.
   */
  repeatBeneficiaryProb: number;
}

/** Uniform weights, for typologies with no strong time preference. */
const FLAT = new Array<number>(24).fill(1);

/** Weighted toward office hours, when impersonating an institution is credible. */
const OFFICE_HOURS = [
  0.2, 0.1, 0.1, 0.1, 0.2, 0.4, 0.8, 1.4, 2.2, 3.0, 3.4, 3.2, 2.6, 3.0, 3.4, 3.2, 2.8, 2.2,
  1.6, 1.2, 0.9, 0.7, 0.5, 0.3,
];

/** Weighted toward evenings and late nights, when victims are alone. */
const EVENING = [
  0.8, 0.6, 0.4, 0.3, 0.3, 0.3, 0.4, 0.6, 0.9, 1.1, 1.2, 1.3, 1.3, 1.4, 1.5, 1.7, 2.0, 2.6,
  3.2, 3.6, 3.4, 2.8, 2.0, 1.3,
];

/** Spread across the whole day, including hours a bank branch is unreachable. */
const ROUND_CLOCK = [
  1.4, 1.3, 1.2, 1.0, 0.9, 0.8, 0.9, 1.1, 1.4, 1.7, 1.8, 1.8, 1.7, 1.8, 1.9, 1.9, 1.8, 1.7,
  1.6, 1.6, 1.6, 1.6, 1.5, 1.4,
];

