/** Typology shares, for the weighted draw. */
export const TYPOLOGY_WEIGHTS: Record<Typology, number> = Object.fromEntries(
  TYPOLOGIES.map((t) => [t.id, t.share]),
) as Record<Typology, number>;

export function typologyById(id: Typology): TypologySpec {
  const spec = TYPOLOGIES.find((t) => t.id === id);
  if (!spec) throw new Error(`Unknown typology: ${id}`);
  return spec;
}

/** Guard against the shares drifting out of normalisation when edited. */
export function validateShares(): void {
  const total = TYPOLOGIES.reduce((s, t) => s + t.share, 0);
  if (Math.abs(total - 1) > 1e-9) {
    throw new Error(`Typology shares must sum to 1, got ${total}`);
  }
}
